namespace sv_f74ea479d0f5432d84ae4d3c09850e3c.Services;

public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        Warehouses.TryGetValue(_currentWarehouseId, out var name) ? name : _currentWarehouseId;

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A - Main Distribution",
            ["WH-002"] = "Warehouse B - East Coast",
            ["WH-003"] = "Warehouse C - West Coast",
            ["WH-004"] = "Warehouse D - Returns Processing",
        };

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }
}

namespace sv_f74ea479d0f5432d84ae4d3c09850e3c.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private Timer? _pollingTimer;
    private int _subscriberCount;
    private int _lastLowStockCount;

    public int CurrentLowStockCount => _lastLowStockCount;

    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulates a database query — returns a random number between 0 and 15.
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    public void StartPolling()
    {
        _subscriberCount++;
        if (_pollingTimer is null)
        {
            _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollingTimer?.Dispose();
            _pollingTimer = null;
        }
    }

    private async void PollCallback(object? state)
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _lastLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh alerts when warehouse changes.
        if (_pollingTimer is not null)
        {
            var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
            _lastLowStockCount = count;
            OnAlertDataChanged?.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        _pollingTimer?.Dispose();
    }
}

@using sv_f74ea479d0f5432d84ae4d3c09850e3c.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label for="warehouse-select"><strong>Warehouse:</strong></label>
    <select id="warehouse-select" class="form-select form-select-sm d-inline-block w-auto ms-2"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= StateHasChanged;
    }
}

@using sv_f74ea479d0f5432d84ae4d3c09850e3c.Services
@inject InventoryAlertService AlertService
