+namespace sv_f74ea479d0f5432d84ae4d3c09850e3c.Services;
+
+public class InventoryAlertService : IDisposable
+{
+    private readonly WarehouseStateService _warehouseState;
+    private Timer? _pollingTimer;
+    private int _subscriberCount;
+    private int _lastLowStockCount;
+
+    public int CurrentLowStockCount => _lastLowStockCount;
+
+    public event Action? OnAlertDataChanged;
+
+    public InventoryAlertService(WarehouseStateService warehouseState)
+    {
+        _warehouseState = warehouseState;
+        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
+    }
+
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        // Simulates a database query — returns a random number between 0 and 15.
+        var count = Random.Shared.Next(0, 16);
+        return Task.FromResult(count);
+    }
+
+    public void StartPolling()
+    {
+        _subscriberCount++;
+        if (_pollingTimer is null)
+        {
+            _pollingTimer = new Timer(PollCallback, null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
+        }
+    }
+
+    public void StopPolling()
+    {
+        _subscriberCount = Math.Max(0, _subscriberCount - 1);
+        if (_subscriberCount == 0)
+        {
+            _pollingTimer?.Dispose();
+            _pollingTimer = null;
+        }
+    }
+
+    private async void PollCallback(object? state)
+    {
+        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
+        _lastLowStockCount = count;
+        OnAlertDataChanged?.Invoke();
+    }
+
